code_example:
int value = 100;

// Const pointer required by function signature
const int* const_p = &value;

// Cast away constness to modify
int* modifiable_p = const_cast<int*>(const_p);

*modifiable_p = 50; // OK: 'value' was not truly const

// Example of removing constness from a reference
void modify_ref(const int& ref) {
    int& writable_ref = const_cast<int&>(ref);
    writable_ref = 5;
}
